import os
# Check thread states for PID 749427
threads = os.listdir('/proc/749427/task/')
states = {}
for t in threads[:50]:
    try:
        with open(f'/proc/749427/task/{t}/stat') as f:
            fields = f.read().split()
            state = fields[2]
            states[state] = states.get(state, 0) + 1
    except:
        pass
print(f'PID 749427: {len(threads)} threads, states: {states}')

